    SetButtonAction(self.BtnAdd, Bind(self, self.OnBtnAdd))
    SetButtonAction(self.BtnMinus, Bind(self, self.OnBtnDel))
    SetButtonAction(self.BtnMinusTen, Bind(self, self.OnBtnTenDel))
