function LadderCompetionTicketDialog:OnChange()
    --又最大持有数
    if self._maxHaveNum > 0 then
        local curHave = 0
        --if checkNumber(self._vo.getItemId) == ActionUtils.GetDailyQuestTicketId() then
        --    curHave = ActionUtils.GetDailyQuestCurTicketAddNum()
        --end
        if curHave >= self._maxHaveNum then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._consumeId)
            GameUtils.Toast(localize("_name_已达到最大数量", {_name_ = vo.name}))
            return
        end
    end

    local num = GoodsUtils.GetThingNo(self._consumeId)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._consumeId)
    if num == 0 then
        if self._isDisableLackMaterialTips then
            GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
        else
            UIModule.CloseDialog(self.controller)
            GoodsUtils.ShowCommonLackMaterialDialog({{goodsId = self._consumeId, num = 1 }})
        end
        return
    end

    GameUtils.Request(self._interface, { num = self._curChangeNum}, function(request, responseTable)
        if checkNumber(responseTable.errCode) ~= 0 then
            return
        end
        local jsonData = responseTable.data

        GoodsUtils.DrawRewards({[1] = {goodsId = self._consumeId, num = -(self._curChangeNum * checkNumber(self._consumeNum))}})
        --if checkNumber(self._vo.getItemId) == ActionUtils.GetDailyQuestTicketId() then
        --    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
        --    comp:AddTicketCount(checkNumber(self._vo.getItemCost))
        --    Events.Broadcast(Constants.EventNames.EveryThingChangeEventName)
        --else
            GoodsUtils.DrawRewards(jsonData.rewards, true)
        --end

        UIModule.CloseDialog(self.controller)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })

        -- 记录剩余购买数量
        if isNotNull(self._remainNumFieldName) then
            local dojo = GameUtils.GetPlayerDojo()
            dojo[self._remainNumFieldName] = jsonData[self._remainNumFieldName]
        end

        if not isNull(self._callback) then
            self._callback()
        end
    end)
end

function LadderCompetionTicketDialog:OnBtnAdd()
    if self._curChangeNum >= self._maxChangeNum then
        return
    end
    self._curChangeNum = self._curChangeNum + 1
    self:FillChangeNum()
end

function LadderCompetionTicketDialog:OnBtnDel()
    if self._curChangeNum <= 1 then
        return
    end
    self._curChangeNum = self._curChangeNum - 1
    self:FillChangeNum()
end

function LadderCompetionTicketDialog:OnBtnTenDel()
    self._curChangeNum = self._curChangeNum - 10
    if self._curChangeNum <= 1 then
        self._curChangeNum = 1
    end
    self:FillChangeNum()
end

function LadderCompetionTicketDialog:OnBtnTenAdd()
    self._curChangeNum = self._curChangeNum + 10
    if self._curChangeNum >= self._maxChangeNum then
        self._curChangeNum = self._maxChangeNum
    end
    self:FillChangeNum()
end

function LadderCompetionTicketDialog:FillChangeNum()
    self.InputFieldNumber.text = self._curChangeNum
    CfUtils.FillCommonBtnConsumePopNode(self.controller.gameObject.transform:Find("Container/Root/Details/CommonBtnConsumePop"), self._consumeId, self._curChangeNum * checkNumber(self._consumeNum), true)

    -- 数量不足时，置灰
    local enough = self:HasEnoughRemainNum(self._curChangeNum)
    local comp = self.FontStyleButton2.gameObject.transform:GetComponent(typeof(CS.Game.Native.Common.FontStyleButton))
    comp:ResetFontStyle(enough and "B3" or "B17")
end

function LadderCompetionTicketDialog:FillConsumeInfo()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._consumeId)
    CfUtils.FillImage(self.ConsumeImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(self._consumeId))
    CfUtils.FillText(self.ConsumeTxtNumber, self._consumeNum)
    CfUtils.FillText(self.ConsumeTxtName, vo.name)
    CfUtils.SetUISwitchImage(self.ConsumeImgFrame, vo.quality)
end

function LadderCompetionTicketDialog:FillGetInfo()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._getId)
    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(self._getId))
    CfUtils.FillText(self.TxtNumber, self._getNum)
    CfUtils.FillText(self.TxtName, vo.name)
    CfUtils.SetUISwitchImage(self.ImgFrame, vo.quality)

    CfUtils.FillText(self.TxtInstructions, localize("兑换_name_数量", {_name_ = vo.name}))
    local scr = CfUtils.GetLuaScr(self.CommonUITitleNode, TitleNodeScrPath)
    if scr then
        scr:Refresh(localize("兑换_name_", {_name_ = vo.name}))
    end
end

function LadderCompetionTicketDialog:FillRemainNum()
    if isNull(self._remainNumFieldName) then
        KTool.SetActive(self.RootRemainNum, false)
        return
    end

    local dojo = GameUtils.GetPlayerDojo()
    local remainNum = dojo[self._remainNumFieldName]

    if isNull(remainNum) then
        KTool.SetActive(self.RootRemainNum, false)
        return
    end

    KTool.SetActive(self.RootRemainNum, true)
    CfUtils.FillText(self.TxtRemainNum, checkInt(remainNum))
end

--- 判断剩余购买数量是否足够
---@param buyNum any
function LadderCompetionTicketDialog:HasEnoughRemainNum(buyNum)
    if isNull(self._remainNumFieldName) then
        return true
    end

    local dojo = GameUtils.GetPlayerDojo()
    local remainNum = dojo[self._remainNumFieldName]

    if isNull(remainNum) then
        return true
    end

    return buyNum <= remainNum
end

